SELECT bh.id, bh.product_id, p.title, p.images AS cover_image, p.price, p.original_price, c.name AS campus_name, u.nick_name AS seller_name, p.status, bh.create_time AS browse_time, p.category_id, cat.name AS category_name FROM browse_history bh INNER JOIN product p ON bh.product_id = p.id AND p.is_deleted = 0 LEFT JOIN campus c ON p.campus_id = c.id LEFT JOIN user u ON p.user_id = u.id LEFT JOIN category cat ON p.category_id = cat.id WHERE bh.user_id = #{userId} AND bh.is_deleted = 0
AND p.category_id = #{categoryId}
AND bh.create_time >= #{beginTime}
AND bh.create_time <= #{endTime}
ORDER BY bh.create_time DESC

SELECT COUNT(*)
FROM browse_history bh
INNER JOIN product p ON bh.product_id = p.id AND p.is_deleted = 0
WHERE bh.user_id = #{userId}
  AND bh.is_deleted = 0

    AND p.category_id = #{categoryId}


    AND bh.create_time >= #{beginTime}


    AND bh.create_time <= #{endTime}

